/* cu-effects:ant-blue — admin hierarchy: 2px radius, layout gray, dark sider, no glass. */
:root {
  --cu-tracking: 0em;
  --cu-font-weight-heading: 600;
}

:root .cu-app-shell {
  background: var(--cu-color-background-subtle);
}

:root .cu-app-shell__header {
  background: var(--cu-color-background-elevated);
  box-shadow: var(--cu-shadow-sm);
  border-block-end: none;
}

:root .cu-app-shell__main {
  background: var(--cu-color-background-subtle);
}

:root .cu-app-shell__sidebar,
:root .cu-sidebar {
  background: var(--cu-color-background-inverse);
  color: var(--cu-color-fg-inverse);
  border-inline-end: none;
}

:root .cu-sidebar__header,
:root .cu-sidebar__toggle {
  color: var(--cu-color-fg-inverse);
}

:root .cu-sidebar__toggle {
  border-color: color-mix(in srgb, var(--cu-color-fg-inverse) 22%, transparent);
}

:root .cu-sidebar__item {
  border-radius: var(--cu-radius-sm);
  color: color-mix(in srgb, var(--cu-color-fg-inverse) 72%, transparent);
}

:root .cu-sidebar__item[aria-current='page'] {
  background: var(--cu-color-palette-brand);
  color: var(--cu-color-fg-inverse);
  font-weight: 600;
}

@media (hover: hover) {
  :root .cu-sidebar__item:hover:not([aria-current='page']),
  :root .cu-sidebar__toggle:hover {
    background: color-mix(in srgb, var(--cu-color-fg-inverse) 8%, transparent);
  }
}

:root .cu-button {
  font-weight: 400;
}

:root .cu-card {
  background: var(--cu-color-background-elevated);
}

:root .cu-card--elevated {
  box-shadow: var(--cu-shadow-md);
  border: none;
}

:root .cu-card--outlined {
  box-shadow: none;
  border: var(--cu-border-width-default, 1px) solid var(--cu-color-border-default);
}

:root .cu-dialog__backdrop {
  background: rgb(0 0 0 / 45%);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

:root .cu-dialog__content {
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  background: var(--cu-color-background-elevated);
  box-shadow: var(--cu-shadow-lg);
}

:root .cu-tab-bar {
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  background: var(--cu-color-background-elevated);
  box-shadow: var(--cu-shadow-sm);
}

:root .cu-input:focus-visible {
  outline: none;
  border-color: var(--cu-color-palette-brand);
  box-shadow: 0 0 0 2px var(--cu-color-background-brand-subtle, color-mix(in srgb, var(--cu-color-palette-brand) 20%, transparent));
}

:root .cu-button:focus-visible {
  outline: 2px solid var(--cu-color-palette-brand);
  outline-offset: 1px;
}

{
  "radius": {
    "sm": { "$value": { "value": 2, "unit": "px" } },
    "md": { "$value": { "value": 2, "unit": "px" } },
    "lg": { "$value": { "value": 4, "unit": "px" } },
    "xl": { "$value": { "value": 6, "unit": "px" } }
  },
  "shadow": {
    "sm": {
      "$value": "0 1px 2px 0 rgba(0, 0, 0, 0.03), 0 1px 6px -1px rgba(0, 0, 0, 0.02)"
    },
    "md": {
      "$value": "0 1px 2px 0 rgba(0, 0, 0, 0.03), 0 2px 8px 0 rgba(0, 0, 0, 0.06)"
    },
    "lg": {
      "$value": "0 6px 16px 0 rgba(0, 0, 0, 0.08), 0 3px 6px -4px rgba(0, 0, 0, 0.12), 0 9px 28px 8px rgba(0, 0, 0, 0.05)"
    }
  },
  "motion": {
    "duration": {
      "fast": { "$value": "100ms" },
      "base": { "$value": "200ms" },
      "slow": { "$value": "300ms" }
    },
    "easing": {
      "standard": { "$value": "cubic-bezier(0.645, 0.045, 0.355, 1)" },
      "enter": { "$value": "cubic-bezier(0.08, 0.82, 0.17, 1)" },
      "exit": { "$value": "cubic-bezier(0.6, 0.04, 0.98, 0.34)" }
    }
  },
  "blur": {
    "surface": { "$value": { "value": 0, "unit": "px" } },
    "overlay": { "$value": { "value": 0, "unit": "px" } },
    "thick": { "$value": { "value": 0, "unit": "px" } }
  },
  "border-width": {
    "$type": "dimension",
    "hairline": { "$value": { "value": 1, "unit": "px" } },
    "default": { "$value": { "value": 1, "unit": "px" } }
  },
  "color": {
    "palette": {
      "brand": { "$value": "#1677ff" },
      "ink": { "$value": "#262626" },
      "paper": { "$value": "#ffffff" }
    },
    "background": {
      "default": { "$value": "{color.palette.paper}" },
      "subtle": { "$value": "#f5f5f5" },
      "elevated": { "$value": "{color.palette.paper}" },
      "brand-subtle": { "$value": "#e6f4ff" },
      "inverse": { "$value": "#001529" }
    },
    "border": {
      "default": { "$value": "#d9d9d9" }
    },
    "fg": {
      "default": { "$value": "{color.palette.ink}" },
      "muted": { "$value": "#8c8c8c" },
      "inverse": { "$value": "#ffffff" }
    }
  },
  "typography": {
    "line-height": {
      "body": { "$value": 1.55 }
    },
    "tracking": {
      "tight": { "$value": "-0.01em" },
      "body": { "$value": "0" }
    }
  }
}
